// loadJobLayout(shortId) → GET /api/portfolio/public/layout/{id}
// Backend bakes from portfolio projects (e.g. WelTel job tracks) + fragments.
export async function loadJobLayout(jobId: string) {
  const res = await fetch(`${octBaseUrl()}/api/portfolio/public/layout/${jobId}`);
  if (!res.ok) return loadBaked(); // fail-open to default matrix
  return LayoutSchema.parse(await res.json());
}
